def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    aggressive_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 80:
                    aggressive_prev.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    competitors = len(alive) + 1
    units = max(1, int(supply // WATER_REQ))
    scarcity = units < competitors

    highest_prev = max(prev_bids) if prev_bids else 0.0
    low_prev = min(prev_bids) if prev_bids else 0.0
    david_prev = None
    cindy_prev = None
    for oid, opp in opponents_status.items():
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is None:
            continue
        if oid == 'David' and opp.get('alive'):
            david_prev = float(bid)
        if oid == 'Cindy' and opp.get('alive'):
            cindy_prev = float(bid)

    critical = hp <= 3 or no_water >= 2
    pressured = hp <= 5 or no_water >= 1

    if critical:
        target = 98.0
        if david_prev is not None:
            target = max(target, david_prev + 3.0)
        if scarcity and cindy_prev is not None and cindy_prev < budget:
            target = max(target, min(cindy_prev + 1.0, budget))
        return float(min(budget, target))

    if scarcity:
        if cindy_prev is not None and cindy_prev >= 140:
            if pressured:
                target = 96.0
                if david_prev is not None:
                    target = max(target, david_prev + 2.0)
                return float(min(budget, target))
            return float(min(budget, 24.0))
        if david_prev is not None:
            if pressured:
                return float(min(budget, david_prev + 2.5))
            return float(min(budget, max(28.0, david_prev - 18.0)))
        return float(min(budget, 35.0 if pressured else 22.0))

    if pressured:
        if david_prev is not None and david_prev < 90:
            return float(min(budget, david_prev + 2.0))
        return float(min(budget, 52.0))

    if highest_prev >= 140:
        return float(min(budget, 16.0))
    if aggressive_prev:
        return float(min(budget, 20.0))
    if low_prev > 0:
        return float(min(budget, max(18.0, low_prev + 1.0)))
    return float(min(budget, 19.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append((oid, o))
        except Exception:
            continue

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', None)
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base willingness: ensure we can win when supply is tight, but avoid Cindy-like overbidding.
    supply_tight = supply <= (MIN_SUPPLY + 1.0)  # around 15-16
    supply_mid = supply <= 20.0

    # If opponents previously bid aggressively, we increase slightly to avoid losing to them.
    opp_pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        opp_pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.5:
        opp_pressure = 0.6
    else:
        opp_pressure = 0.3

    # HP urgency
    if my_hp <= 2:
        hp_factor = 1.0
    elif my_hp <= 4:
        hp_factor = 0.75
    else:
        hp_factor = 0.55

    # If we've already gone without water multiple days, bid more.
    if my_no_water_days >= 3:
        no_water_factor = 1.0
    elif my_no_water_days >= 1:
        no_water_factor = 0.85
    else:
        no_water_factor = 0.6

    # Target bid range
    if supply_tight:
        base = DAILY_SALARY * 0.65
    elif supply_mid:
        base = DAILY_SALARY * 0.55
    else:
        base = DAILY_SALARY * 0.45

    target = base * (0.7 + 0.6 * opp_pressure) * (0.5 + 0.5 * hp_factor) * (0.5 + 0.5 * no_water_factor)

    # Cap to budget and avoid extreme overbids
    # Keep below Cindy's observed max (~155) unless my HP is critical.
    if my_hp <= 2:
        cap = min(my_budget, DAILY_SALARY * 1.1)
    else:
        cap = min(my_budget, DAILY_SALARY * 0.95)

    bid = max(0.0, min(float(my_budget), target, cap))

    # If budget is too low, bid whatever we can.
    if my_budget <= 1.0:
        return max(0.0, my_budget)

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    highest_prev_bid = 0.0
    num_bidding_opponents = 0
    num_desperate_opponents = 0

    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            bid = prev_trace['bid']
            highest_prev_bid = max(highest_prev_bid, bid)
            num_bidding_opponents += 1

            opp_hp_after_prev_day = prev_trace.get('hp_after', opp['hp'])
            if opp_hp_after_prev_day <= opp['water_requirement'] * 1.5:
                num_desperate_opponents += 1

    my_desperation_factor = 1.0
    if my_hp <= WATER_REQ * 1.0:
        my_desperation_factor = 1.5
    if my_hp <= WATER_REQ * 0.5:
        my_desperation_factor = 2.5
    if my_status['no_water_days'] > 0:
        my_desperation_factor *= (1 + my_status['no_water_days'] * 0.7)

    num_water_slots = int(current_supply // WATER_REQ)

    base_bid = DAILY_SALARY * 0.6 * my_desperation_factor

    if highest_prev_bid > 0:
        if num_water_slots <= len(alive_opponents):
            base_bid = max(base_bid, highest_prev_bid * 1.1)
        else:
            base_bid = max(base_bid, highest_prev_bid * 1.05)

    if num_desperate_opponents >= num_water_slots and num_water_slots < len(alive_opponents) + 1:
        base_bid = max(base_bid, DAILY_SALARY * 1.0 * my_desperation_factor)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 3:
        base_bid *= 1.2
    elif current_day <= 2:
        base_bid *= 0.9

    final_bid = min(my_budget, base_bid)

    if my_hp <= WATER_REQ * 1.5 and my_budget > 0 and final_bid < DAILY_SALARY * 0.4:
        final_bid = min(my_budget, DAILY_SALARY * 0.4 * my_desperation_factor)

    if my_hp <= WATER_REQ * 0.5 and my_budget > 0:
        final_bid = min(my_budget, my_budget * 0.98)

    if my_budget > 0 and final_bid < 1.0:
        final_bid = min(my_budget, 1.0)

    return max(1.0, final_bid)
